import sys
from collections import deque

def find_path(n, m, k, grid):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    start = None
    end = None

    # Find the positions of 'S' and 'T'
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                end = (i, j)

    # BFS to find the shortest path
    queue = deque([(start, set(), 0, '')])
    visited = set()
    visited.add(start + (frozenset(),))

    while queue:
        (x, y), seen_types, steps, path = queue.popleft()

        if (x, y) == end:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                new_type = grid[nx][ny]
                if new_type.islower():
                    new_seen_types = seen_types | {new_type}
                    if len(new_seen_types) <= k:
                        new_state = (nx, ny, frozenset(new_seen_types))
                        if new_state not in visited:
                            visited.add(new_state)
                            queue.append((new_state[:2], new_state[2], steps + 1, path + new_type))

    return "-1"

